// ============================================================================
// FreeLang Query Runner 모듈 - 통합 쿼리 실행 파이프라인
// ============================================================================
// 목표: planner→physical_plan→executor→result_set 통합 파이프라인 facade
// 원리:
//   1. QueryRunner: 모든 실행 단계를 통합 관리
//   2. query_runner_execute: SQL 문자열 → 파싱 → 계획 → 실행 → 결과
//   3. 에러 처리: 각 단계별 에러 코드 전파 (QR_ERR_*)
// 구조:
//   - 상수 정의 (에러 코드, 제한값)
//   - PipelineStats, QueryRunner 구조체
//   - 초기화 및 실행 함수 (8개 공개 API)
//   - 헬퍼 함수
// ============================================================================

module query_runner {
    // === 에러 코드 (170-172) ===
    const QR_OK:        i32 = 0;
    const QR_ERR_PLAN:  i32 = 170;
    const QR_ERR_EXEC:  i32 = 171;
    const QR_ERR_PARSE: i32 = 172;

    // === 제한값 ===
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 데이터 구조체 ===

    // 파이프라인 통계 및 상태
    struct PipelineStats {
        parse_ok:    bool;
        plan_type:   i32;
        op_count:    i32;
        result_rows: i32;
        error_code:  i32;
    }

    // 통합 쿼리 실행 엔진
    struct QueryRunner {
        pq:        query_parser.ParsedQuery;
        exec_plan: planner.ExecPlan;
        phys_plan: physical_plan.PhysicalPlan;
        ex:        executor.Executor;
        result:    result_set.ResultSet;
        stats:     PipelineStats;
        has_error: bool;
        error_code: i32;
    }

    // === 초기화 함수 ===

