// === 헬퍼: 정수를 문자열로 ===
fn to_string(n: i32) -> string {
    if n == 0 {
        return "0";
    }

    let negative = false;
    if n < 0 {
        negative = true;
        n = 0 - n;
    }

    let result = "";
    let temp = n;

    for temp > 0 {
        let digit = temp % 10;
        let ch = char_from_code(48 + digit);  // '0' = 48
        result = ch + result;
        temp = temp / 10;
    }

    if negative {
        result = "-" + result;
    }

    return result;
}

// === Main ===
fn main() {
    // 서버 시작 (별도 스레드 필요 - 여기서는 간단히 테스트)
    init_bns_server();

    // 테스트 모드: 몇 가지 엔드포인트 호출
    test_all_endpoints();
}

